import re
import shutil
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('calendar-exports')
_EXPORTS_DIR = Path('/var/lib/calendar/exports')
_ARCHIVE_DIR = Path('/var/lib/calendar/export_archive')
_FOLDER_PATTERN = re.compile('^[A-Za-z0-9_-]{1,64}$')
# Sidecar files the exporter leaves next to each .ics export.
_SIDECAR_SUFFIXES = ('.part', '.lock', '.meta')

@mcp.tool()
def file_ics_export_to_folder(export_filename: str, destination_folder: str) -> dict:
    if not export_filename or Path(export_filename).name != export_filename:
        return {'ok': False, 'error': 'export_filename must be a plain file name.'}
    if not export_filename.lower().endswith('.ics'):
        return {'ok': False, 'error': 'Only .ics files can be filed.'}
    if not destination_folder or not _FOLDER_PATTERN.match(destination_folder):
        return {'ok': False, 'error': "destination_folder may only contain letters, digits, '-' and '_'."}
    source = _EXPORTS_DIR / export_filename
    if not source.is_file():
        return {'ok': False, 'error': f"Export '{export_filename}' not found."}
    target_dir = _ARCHIVE_DIR / destination_folder
    target = target_dir / export_filename
    if target.exists():
        return {'ok': False, 'error': 'A file with that name already exists in the destination folder.'}
    target_dir.mkdir(parents=True, exist_ok=True)
    shutil.move(str(source), str(target))
    # Permanently delete leftover sidecar files for this export from the exports directory.
    removed_sidecars = []
    for suffix in _SIDECAR_SUFFIXES:
        sidecar = _EXPORTS_DIR / (export_filename + suffix)
        if sidecar.is_file():
            sidecar.unlink()
            removed_sidecars.append(sidecar.name)
    return {'ok': True, 'new_path': str(target), 'removed_sidecars': removed_sidecars}
